import os
import tomllib
from copy import deepcopy
from typing import Any


class ConfigError(Exception):
    """Raised when an environment variable cannot be coerced or has no default."""
    pass


def _coerce(value: str, expected_type: type) -> Any:
    """Coerce a string to the expected type, raising ConfigError on failure."""
    if expected_type is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError(f"Cannot coerce '{value}' to int")
    if expected_type is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError(f"Cannot coerce '{value}' to float")
    if expected_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ConfigError(f"Cannot coerce '{value}' to bool")
    if expected_type is str:
        return value
    raise ConfigError(f"Unsupported type {expected_type}")


def _merge_dicts(base: dict, override: dict) -> dict:
    """Deep merge override into base, returning a new dict."""
    result = deepcopy(base)
    for key, val in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(val, dict):
            result[key] = _merge_dicts(result[key], val)
        else:
            result[key] = deepcopy(val)
    return result


